    const prefix = parsed.prefix;

    const runPass = async (
      args: string[],
      stdin?: string,
    ): Promise<string> => {
      const cmd = new Deno.Command("pass", {
        args,
        env: buildEnv(storeDir, parsed.extraEnv),
        // Without this Deno merges `env` into the parent environment instead of
        // replacing it, and the allowlist filters nothing.
        clearEnv: true,
        stdin: stdin ? "piped" : "null",
        stdout: "piped",
        stderr: "piped",
      });

      const proc = cmd.spawn();

      if (stdin) {
        const writer = proc.stdin.getWriter();
        await writer.write(new TextEncoder().encode(stdin));
        await writer.close();
      }

      const { code, stdout, stderr } = await proc.output();

      if (code !== 0) {
        let errMsg = new TextDecoder().decode(stderr).trim();
        // On `insert` the secret went in on stdin, and a CLI that rejects a
        // value can quote it back. The host publishes thrown messages to the
        // trace backend, so strip the value we know we sent.
        if (stdin) errMsg = redactSecret(errMsg, stdin);
        const commandDesc = `pass ${args.join(" ")}`;
        throw new Error(
          `${commandDesc} exited with code ${code}${
            errMsg ? `: ${errMsg}` : ""
          }`,
        );
      }

      return stripTrailingNewline(new TextDecoder().decode(stdout));
    };

    const prefixKey = (key: string): string => {
      assertSafeKey(key);
      return prefix ? `${prefix}/${key}` : key;
    };

